#!/usr/bin/env bash
# Transactional repair: fit relevant Qwen tool schemas within the calibrated context budget.
set -euo pipefail
readonly APP='/srv/aibrain/production/apps/AI_Brain_Build'
readonly SERVICE="$APP/src/aibrain_rkllm/service.py"
readonly FACTORY="$APP/src/aibrain_rkllm/wsgi_factory.py"
readonly TESTS="$APP/tests/test_service.py"
readonly PYTHON='/srv/aibrain/production/runtime/rkllm-venv/bin/python3'
readonly SERVICE_NAME='aibrain-rkllm.service'
readonly HEALTH_URL='http://127.0.0.1:8081/healthz'
readonly BACKUP_ROOT='/srv/aibrain/test/backups'
readonly SOURCE_SHA='082d732bd35702d1bae18585c93bf7d26efd71fb4323c6fcee28f4db918d2575'
readonly FACTORY_SHA='8ecef84f33fd778a89ab74995783808aeb0f676e7a1703bfeee6574a18b22eed'
readonly TESTS_SHA='c638c59dbfc1bb41dc9930d7c47b1dfc7d0bfc23c42f4e99676b7391877d2cb5'

fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
require_sha() {
  local path="$1" expected="$2" actual
  [[ -f "$path" ]] || fail "Required file is missing: $path"
  actual=$(sha256sum "$path" | awk '{print $1}')
  [[ "$actual" == "$expected" ]] || fail "SHA-256 mismatch for $path"
}
wait_for_health() {
  for _ in $(seq 1 45); do
    curl -fsS "$HEALTH_URL" >/dev/null && return 0
    sleep 1
  done
  return 1
}
assert_loopback() {
  ss -ltnH | awk '$4 == "127.0.0.1:8081" {found=1} END {exit !found}'
  ! ss -ltnH | awk '$4 ~ /:8081$/ && $4 != "127.0.0.1:8081" {exit 0} END {exit 1}'
}
run_tests() {
  PYTHONPATH="$APP/src" "$PYTHON" - "$TESTS" <<'PY'
import runpy, sys
tests = runpy.run_path(sys.argv[1])
for name in sorted(key for key in tests if key.startswith("test_")):
    tests[name]()
    print(f"PASS {name}")
PY
}
probe_maintenance_projection() {
  local response
  response=$(curl --fail --silent --show-error --max-time 120 \
    -H 'Content-Type: application/json' \
    -d '{"model":"rkllm","max_tokens":96,"messages":[{"role":"system","content":"For this diagnostic, call the offered maintenance_inspect function. Return no prose."},{"role":"user","content":"Run a maintenance inspection."}],"tools":[{"type":"function","function":{"name":"maintenance_inspect","description":"Read-only maintenance inspection.","parameters":{"type":"object","properties":{}}}},{"type":"function","function":{"name":"unrelated_planner","description":"Plan unrelated work with a very large schema that must not be selected for this inspection.","parameters":{"type":"object","properties":{"payload":{"type":"string","description":"irrelevant"}}}}]}' \
    http://127.0.0.1:8081/v1/chat/completions)
  "$PYTHON" - "$response" <<'PY'
import json, sys
body = json.loads(sys.argv[1])
choice = body["choices"][0]
calls = choice["message"].get("tool_calls", [])
assert choice["finish_reason"] == "tool_calls", choice
assert len(calls) == 1, choice
assert calls[0]["function"]["name"] == "maintenance_inspect", calls
assert calls[0]["function"]["arguments"] == "{}", calls
PY
}

require_sha "$SERVICE" "$SOURCE_SHA"
require_sha "$FACTORY" "$FACTORY_SHA"
require_sha "$TESTS" "$TESTS_SHA"
STAMP=$(date +%Y%m%d-%H%M%S)
BACKUP_DIR="$BACKUP_ROOT/rkllm-native-tool-budget-$STAMP"
mkdir -p "$BACKUP_DIR"
cp -a "$SERVICE" "$BACKUP_DIR/service.py"
cp -a "$TESTS" "$BACKUP_DIR/test_service.py"
SERVICE_MODE=$(stat -c '%a' "$SERVICE")
TESTS_MODE=$(stat -c '%a' "$TESTS")
APPLIED=0
restore() {
  if [[ "$APPLIED" -eq 1 ]]; then
    cp -a "$BACKUP_DIR/service.py" "$SERVICE"
    cp -a "$BACKUP_DIR/test_service.py" "$TESTS"
    chmod "$SERVICE_MODE" "$SERVICE"
    chmod "$TESTS_MODE" "$TESTS"
    systemctl --user restart "$SERVICE_NAME" || true
    wait_for_health || true
  fi
}
trap restore ERR EXIT

base64 -d >"$SERVICE" <<'SERVICE_PAYLOAD'

SERVICE_PAYLOAD
base64 -d >"$TESTS" <<'TESTS_PAYLOAD'

TESTS_PAYLOAD
chmod "$SERVICE_MODE" "$SERVICE"
chmod "$TESTS_MODE" "$TESTS"
APPLIED=1

"$PYTHON" -m py_compile "$SERVICE" "$TESTS"
run_tests
systemctl --user restart "$SERVICE_NAME"
wait_for_health || fail 'RKLLM service did not become healthy'
assert_loopback || fail 'RKLLM listener is not loopback-only'
probe_maintenance_projection || fail 'Maintenance schema projection did not produce a validated tool call'

APPLIED=0
trap - ERR EXIT
printf 'PASS: native tool budget repair installed and verified.\n'
printf 'Backups: %s\n' "$BACKUP_DIR"
printf 'Next WebUI check: Jarvis, run a maintenance inspection.\n'
